  const tiers = [{ upTo: 100, unitRateCents: 10 }];
  const grants = [{ grantId: 'g1', remainingCents: 900, effectiveFromMs: 0, expiresAtMs: 50_000 }];

  const inv = buildInvoice({
    invoiceId: 'inv-t04',
